/** NodeSource's palette, as the console has it (`@ns-private/colors`). */
var palette = {
	white: "rgb(255, 255, 255)",
	light3: "rgb(245, 247, 247)",
	light2: "rgb(225, 231, 230)",
	lightGrey: "rgb(137, 161, 157)",
	baseGrey: "rgb(76, 88, 89)",
	dark1: "rgb(61, 70, 71)",
	dark2: "rgb(53, 61, 62)",
	dark3: "rgb(46, 53, 53)",
	dark4: "rgb(32, 37, 37)",
	teal: "rgb(102, 204, 187)",
	lavender: "rgb(162, 143, 204)",
	nSolidGreen: "rgb(90, 200, 120)",
	actionBlue: "rgb(76, 181, 255)",
	alertRed: "rgb(255, 96, 64)",
	warningYellow: "rgb(255, 183, 38)"
};
palette.dark4, palette.baseGrey, palette.white, palette.light2, palette.light2, palette.light2, palette.actionBlue;
