/** uPlot's stylesheet (MIT, Leon Sorokin), as uplot/dist/uPlot.min.css ships it. */
var UPLOT_CSS = `.uplot, .uplot *, .uplot *::before, .uplot *::after {box-sizing: border-box;}.uplot {font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Noto Sans", sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji";line-height: 1.5;width: min-content;}.u-title {text-align: center;font-size: 18px;font-weight: bold;}.u-wrap {position: relative;user-select: none;}.u-over, .u-under {position: absolute;}.u-under {overflow: hidden;}.uplot canvas {display: block;position: relative;width: 100%;height: 100%;}.u-axis {position: absolute;}.u-legend {font-size: 14px;margin: auto;text-align: center;}.u-inline {display: block;}.u-inline * {display: inline-block;}.u-inline tr {margin-right: 16px;}.u-legend th {font-weight: 600;}.u-legend th > * {vertical-align: middle;display: inline-block;}.u-legend .u-marker {width: 1em;height: 1em;margin-right: 4px;background-clip: padding-box !important;}.u-inline.u-live th::after {content: ":";vertical-align: middle;}.u-inline:not(.u-live) .u-value {display: none;}.u-series > * {padding: 4px;}.u-series th {cursor: pointer;}.u-legend .u-off > * {opacity: 0.3;}.u-select {background: rgba(0,0,0,0.07);position: absolute;pointer-events: none;}.u-cursor-x, .u-cursor-y {position: absolute;left: 0;top: 0;pointer-events: none;will-change: transform;}.u-hz .u-cursor-x, .u-vt .u-cursor-y {height: 100%;border-right: 1px dashed #607D8B;}.u-hz .u-cursor-y, .u-vt .u-cursor-x {width: 100%;border-bottom: 1px dashed #607D8B;}.u-cursor-pt {position: absolute;top: 0;left: 0;border-radius: 50%;border: 0 solid;pointer-events: none;will-change: transform;background-clip: padding-box !important;}.u-axis.u-off, .u-select.u-off, .u-cursor-x.u-off, .u-cursor-y.u-off, .u-cursor-pt.u-off {display: none;}`;
var LIGHT = `
  --skv-bg: ${palette.white};
  --skv-panel: ${palette.light3};
  --skv-input: ${palette.white};
  --skv-title: ${palette.light2};
  --skv-fg: ${palette.dark2};
  --skv-text: ${palette.baseGrey};
  --skv-muted: ${palette.baseGrey};
  --skv-border: ${palette.light2};
  --skv-grid: ${palette.light2};
  --skv-dim: ${palette.light2};
  --skv-accent: rgb(45, 129, 189);
  --skv-button: ${palette.light2};
  --skv-button-fg: ${palette.baseGrey};
  --skv-switch: ${palette.light3};
  --skv-switch-on: ${palette.light2};
  --skv-switch-on-fg: ${palette.baseGrey};`;
var DARK = `
  --skv-bg: ${palette.dark2};
  --skv-panel: ${palette.dark3};
  --skv-input: ${palette.dark4};
  --skv-title: ${palette.baseGrey};
  --skv-fg: ${palette.light2};
  --skv-text: rgb(184, 198, 196);
  --skv-muted: ${palette.lightGrey};
  --skv-border: ${palette.dark1};
  --skv-grid: ${palette.baseGrey};
  --skv-dim: ${palette.dark1};
  --skv-accent: ${palette.actionBlue};
  --skv-button: ${palette.baseGrey};
  --skv-button-fg: ${palette.white};
  --skv-switch: rgb(0, 0, 0);
  --skv-switch-on: ${palette.baseGrey};
  --skv-switch-on-fg: ${palette.white};`;
/**
* The widgets' stylesheet: color tokens on :root (light, dark by the
* system's preference or `data-theme`), then the widgets' own rules.
*/
var VIZ_CSS = `
:root {${LIGHT}
  --skv-font: "Source Sans Pro", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --skv-mono: "Source Code Pro", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --skv-tip-bg: ${palette.white};
  --skv-tip-fg: ${palette.baseGrey};
  --skv-good: ${palette.nSolidGreen};
  --skv-bad: ${palette.alertRed};
  --skv-warn: ${palette.warningYellow};
  color-scheme: light;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {${DARK}
    color-scheme: dark;
  }
}
:root[data-theme="dark"] {${DARK}
  color-scheme: dark;
}
/* A light panel on the dark page, as the console's menus and dropdowns are. */
.skv-light {${LIGHT}
  color-scheme: light;
}
.skv { font: 14px/1.45 var(--skv-font); color: var(--skv-fg); }
.skv *, .skv *::before, .skv *::after { box-sizing: border-box; }
.skv-flame, .skv-fleet-plot { position: relative; outline: none; }
.skv-flame:focus-visible { box-shadow: 0 0 0 2px var(--skv-accent); }
.skv-flame canvas, .skv-fleet-plot canvas { display: block; }
.skv-fleet-xtitle { position: absolute; transform: translateX(-50%); white-space: nowrap; }
.skv-fleet-ytitle { position: absolute; width: 0; height: 0; }
.skv-fleet-plot:focus-visible { outline: 2px solid var(--skv-accent); outline-offset: 2px; }
.skv-tip { position: absolute; z-index: 10; pointer-events: none; max-width: 300px;
  background: var(--skv-tip-bg); color: var(--skv-tip-fg); border: 0;
  border-radius: 2px; padding: 8px 10px; box-shadow: 0 2px 12px rgba(0, 0, 0, 0.35); font-size: 12px; }
.skv-tip-title { font-weight: 600; overflow-wrap: anywhere; }
.skv-tip-sub { color: ${palette.lightGrey}; margin: 2px 0 6px; overflow-wrap: anywhere; }
.skv-tip table { border-collapse: collapse; }
.skv-tip th { text-align: left; font-weight: 400; color: ${palette.lightGrey}; padding: 1px 10px 1px 0; }
.skv-tip td { padding: 1px 8px 1px 0; font-weight: 600; font-variant-numeric: tabular-nums; white-space: nowrap; }
.skv-toolbar { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin-bottom: 8px; }
.skv-push { margin-left: auto; }
.skv-input, .skv-select { font: inherit; height: 30px; padding: 0 10px; border: 1px solid var(--skv-border);
  border-radius: 2px; background: var(--skv-input); color: var(--skv-fg); }
textarea.skv-input { height: auto; padding: 6px 10px; }
.skv-input::placeholder { color: var(--skv-muted); font-style: italic; }
.skv-input { width: min(340px, 100%); }
.skv-button { font: inherit; font-size: 12px; letter-spacing: 1.2px; text-transform: uppercase;
  display: inline-flex; align-items: center; justify-content: center; gap: 6px; height: 30px; padding: 0 14px;
  border: 0; border-radius: 2px; background: var(--skv-button); color: var(--skv-button-fg);
  cursor: pointer; text-decoration: none; white-space: nowrap; transition: filter 0.3s; }
.skv-button:hover { filter: brightness(0.85); }
.skv-button:active { filter: brightness(0.75); }
.skv-button:disabled { background: transparent; color: var(--skv-muted); border: 1px solid var(--skv-muted);
  cursor: default; filter: none; }
.skv-button.primary { background: ${palette.actionBlue}; color: ${palette.white}; }
.skv-button.danger { background: ${palette.alertRed}; color: ${palette.white}; }
.skv-muted { color: var(--skv-muted); }
.skv-focus-details { margin: 8px 0; padding: 10px 12px; border-left: 2px solid var(--skv-border); background: var(--skv-panel); }
.skv-columns { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.4fr); gap: 24px; margin-top: 18px; }
@media (max-width: 760px) { .skv-columns { grid-template-columns: minmax(0, 1fr); } }
.skv-h { font-size: 14px; font-weight: 600; margin: 0 0 8px; }
.skv-shares { list-style: none; margin: 0; padding: 0; }
.skv-share-row { display: grid; grid-template-columns: minmax(0, 11em) minmax(30px, 1fr) auto 3.6em; gap: 8px;
  align-items: center; width: 100%; padding: 3px 0; background: none; border: 0; font: inherit;
  color: inherit; text-align: left; }
button.skv-share-row { cursor: pointer; }
button.skv-share-row:hover .skv-share-label { color: var(--skv-accent); text-decoration: underline; }
.skv-share-label { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.skv-share-track { height: 10px; }
.skv-share-bar { display: block; height: 100%; border-radius: 3px; min-width: 2px; }
.skv-share-value, .skv-share-pct { font-variant-numeric: tabular-nums; text-align: right; white-space: nowrap; }
.skv-share-pct { color: var(--skv-muted); }
.skv-table { width: 100%; border-collapse: collapse; }
.skv-table th { text-align: left; font-weight: 400; font-size: 12px; line-height: 1.2; letter-spacing: 2px;
  text-transform: uppercase; color: var(--skv-muted); padding: 6px 10px; vertical-align: bottom; }
.skv-table th button { text-transform: inherit; letter-spacing: inherit; color: inherit; font-weight: inherit; }
.skv-table td { padding: 8px 10px; color: var(--skv-text); vertical-align: top; border-left: 1px solid var(--skv-bg); }
.skv-table td:first-child { border-left: 0; }
.skv-table tbody tr:nth-child(odd) { background: var(--skv-panel); }
.skv-table td a { color: var(--skv-fg); }
.skv-table .skv-num { text-align: right; white-space: nowrap; font-variant-numeric: tabular-nums; }
.skv-sub { color: var(--skv-muted); font-size: 11px; overflow-wrap: anywhere; }
.skv-swatch { display: inline-block; width: 9px; height: 9px; border-radius: 50%; margin-right: 6px; }
.skv-diff-legend .skv-swatch { border-radius: 2px; margin-left: 10px; margin-right: 4px; }
.skv-link { background: none; border: 0; padding: 0; font: inherit; color: inherit; cursor: pointer;
  text-align: left; overflow-wrap: anywhere; }
.skv-link:hover { color: var(--skv-accent); text-decoration: underline; }
.skv-legend { display: flex; flex-wrap: wrap; gap: 4px 14px; list-style: none; padding: 0; margin: 8px 0 0; font-size: 12px; }
.skv-stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 10px; }
.skv-stat { background: var(--skv-panel); border: 0; border-radius: 2px; padding: 10px 14px; }
.skv-stat-value { font-size: 26px; font-weight: 300; line-height: 1.2; font-variant-numeric: tabular-nums; }
.skv-stat-label { color: var(--skv-muted); font-size: 11px; letter-spacing: 1.5px; text-transform: uppercase; }
.skv-timeseries { width: 100%; }
.skv-timeseries .uplot { width: 100%; }
.skv-spark { display: block; width: 100%; height: 28px; overflow: visible; }
.skv-chip { display: inline-block; border: 1px solid var(--skv-border); border-radius: 999px;
  padding: 1px 8px; font-size: 11px; white-space: nowrap; }
.skv-scatter { position: relative; }
.skv-scatter canvas { display: block; }
.skv-lanes { position: absolute; left: 0; top: 0; }
.skv-lane { position: absolute; left: 0; right: 0; display: flex; align-items: center; gap: 7px;
  padding: 0 6px 0 2px; border: 0; border-radius: 2px; background: none; color: var(--skv-fg);
  font: inherit; font-size: 12px; text-align: left; }
button.skv-lane { cursor: pointer; }
button.skv-lane:hover { background: var(--skv-panel); }
button.skv-lane:focus-visible { outline: 2px solid var(--skv-accent); outline-offset: -2px; }
.skv-lane[aria-pressed="false"] { color: var(--skv-muted); }
.skv-lane[aria-pressed="false"] .skv-lane-name { text-decoration: line-through; }
.skv-lane-dot { flex: none; width: 10px; height: 10px; border: 2px solid; border-radius: 50%; }
.skv-lane-name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.skv-lane-count { color: var(--skv-muted); font-variant-numeric: tabular-nums; }
.skv-waterfall { font-size: 12px; }
.skv-wf-head, .skv-wf-row { display: grid; grid-template-columns: minmax(140px, 34%) minmax(0, 1fr); align-items: center; }
.skv-wf-head { height: 24px; color: var(--skv-muted); border-bottom: 1px solid var(--skv-border); }
.skv-wf-axis { position: relative; height: 100%; }
.skv-wf-axis span { position: absolute; top: 4px; transform: translateX(-50%); white-space: nowrap;
  font-variant-numeric: tabular-nums; }
.skv-wf-row { height: 24px; cursor: pointer; }
.skv-wf-row:hover, .skv-wf-row.is-selected { background: var(--skv-panel); }
.skv-wf-row.is-selected { box-shadow: inset 2px 0 0 var(--skv-accent); }
.skv-wf-row.is-faint { opacity: 0.35; }
.skv-svcmap { overflow-x: auto; margin: 0; }
.skv-svcmap svg { display: block; font-family: var(--skv-font); }
.skv-svcmap-node, .skv-svcmap-edge { cursor: pointer; outline: none; }
.skv-svcmap-box { fill: var(--skv-input); stroke: var(--skv-border); stroke-width: 1px; }
.skv-svcmap-node.is-external .skv-svcmap-box { fill: none; stroke: var(--skv-muted); stroke-dasharray: 4 3; }
.skv-svcmap-node:hover .skv-svcmap-box, .skv-svcmap-node:focus-visible .skv-svcmap-box,
.skv-svcmap-node.is-selected .skv-svcmap-box { stroke: var(--skv-accent); stroke-width: 2px; }
.skv-svcmap-name { font-size: 12px; font-weight: 600; fill: var(--skv-fg); }
.skv-svcmap-sub { font-size: 11px; fill: var(--skv-muted); }
.skv-svcmap-bad { fill: var(--skv-bad); }
.skv-svcmap-line { fill: none; stroke: var(--skv-muted); stroke-width: 1.5px; }
.skv-svcmap-edge.is-error .skv-svcmap-line { stroke: var(--skv-bad); }
.skv-svcmap-hit { fill: none; stroke: transparent; stroke-width: 14px; }
.skv-svcmap-edge:hover .skv-svcmap-line, .skv-svcmap-edge:focus-visible .skv-svcmap-line,
.skv-svcmap-edge.is-selected .skv-svcmap-line { stroke: var(--skv-accent); stroke-width: 2.5px; }
.skv-svcmap-label { font-size: 11px; fill: var(--skv-fg); paint-order: stroke; stroke: var(--skv-bg);
  stroke-width: 4px; stroke-linejoin: round; font-variant-numeric: tabular-nums; }
.skv-svcmap-arrow { fill: var(--skv-muted); }
.skv-svcmap-arrow.is-error { fill: var(--skv-bad); }
.skv-wf-row:focus-visible { outline: 2px solid var(--skv-accent); outline-offset: -2px; }
.skv-wf-label { display: flex; align-items: center; gap: 4px; min-width: 0; overflow: hidden;
  white-space: nowrap; padding-right: 8px; }
.skv-wf-name { overflow: hidden; text-overflow: ellipsis; }
.skv-wf-row.is-error .skv-wf-name { color: var(--skv-bad); }
.skv-wf-toggle { flex: none; width: 16px; height: 16px; padding: 0; border: 0; background: none;
  color: var(--skv-muted); font-size: 10px; cursor: pointer; }
.skv-wf-track { position: relative; height: 100%; }
.skv-wf-bar { position: absolute; top: 6px; height: 12px; border-radius: 2px; }
.skv-wf-row.is-error .skv-wf-bar { outline: 2px solid var(--skv-bad); outline-offset: -1px; }
.skv-wf-dur { position: absolute; top: 4px; color: var(--skv-muted); white-space: nowrap;
  font-variant-numeric: tabular-nums; }
.skv-wf-dur.is-inside { color: rgb(32, 37, 37); }
.skv-span-head { display: flex; flex-wrap: wrap; align-items: baseline; gap: 6px 12px; margin-bottom: 12px; }
.skv-span-name { font-size: 14px; overflow-wrap: anywhere; }
.skv-span .skv-h { margin-top: 12px; }
.skv-span summary { cursor: pointer; }
.skv-kv { display: grid; grid-template-columns: minmax(120px, max-content) minmax(0, 1fr); gap: 2px 14px;
  margin: 0; font-size: 12px; }
.skv-kv > div { display: contents; }
.skv-kv dt { color: var(--skv-muted); overflow-wrap: anywhere; }
.skv-kv dd { margin: 0; overflow-wrap: anywhere; font-family: var(--skv-mono); }
.skv-events { list-style: none; padding: 0; margin: 0; display: grid; gap: 8px; }
.skv-timeseries .uplot { font-family: var(--skv-font); }
.skv-timeseries .u-legend { font-size: 12px; text-align: left; color: var(--skv-fg); }
.skv-timeseries .u-legend .u-marker { border-radius: 50%; }
.skv-timeseries .u-select { background: color-mix(in srgb, var(--skv-accent) 18%, transparent); }
.skv-key { display: inline-block; width: 14px; height: 0; border-top: 2px solid var(--skv-muted);
  vertical-align: middle; margin-right: 6px; }
.skv-ts { min-width: 0; }
.skv-ts-far { margin: 0 0 4px; font-size: 11px; color: var(--skv-muted); text-align: right; }
.skv-ts-readout { display: flex; flex-wrap: wrap; align-items: baseline; gap: 2px 12px; min-height: 18px;
  margin: 0 0 2px; font-size: 12px; line-height: 16px; color: var(--skv-muted); }
.skv-ts-title { color: var(--skv-fg); font-size: 13px; font-weight: 600; margin-right: 2px; }
.skv-ts-items { display: contents; }
.skv-ts-item { display: inline-flex; align-items: baseline; gap: 5px; white-space: nowrap; min-width: 0; }
.skv-ts-item .skv-key { margin: 0; align-self: center; }
.skv-ts-name { max-width: 16em; overflow: hidden; text-overflow: ellipsis; }
.skv-ts-value { color: var(--skv-fg); font-weight: 600; font-variant-numeric: tabular-nums; min-width: 4ch; }
.skv-ts-item.is-empty .skv-ts-value { color: var(--skv-muted); font-weight: 400; }
.skv-ts-readout .skv-ts-far { margin: 0; }
.skv-ts-time { margin-left: auto; font-variant-numeric: tabular-nums; white-space: nowrap; }
${UPLOT_CSS}
`;
