//#region src/report/html.ts
/** The page around a report: full width on phones, a column on wide screens. */
var REPORT_CSS = `
html, body { margin: 0; background: var(--skv-bg); color: var(--skv-fg); }
.skv-report { max-width: 1120px; margin: 0 auto; padding: 24px 16px 48px; }
.skv-report h1 { font-size: 22px; line-height: 1.25; margin: 0 0 4px; }
.skv-report h2 { font-size: 16px; margin: 0 0 10px; }
.skv-report p { max-width: 75ch; }
.skv-report-head { border-bottom: 1px solid var(--skv-border); padding-bottom: 14px; margin-bottom: 8px; }
.skv-source { display: flex; flex-wrap: wrap; gap: 4px 22px; margin: 10px 0 0; font-size: 12px; }
.skv-source dt { color: var(--skv-muted); }
.skv-source dd { margin: 0; overflow-wrap: anywhere; }
.skv-section { margin-top: 26px; }
.skv-note { color: var(--skv-muted); font-size: 12px; margin: 8px 0 0; }
.skv-scroll { overflow-x: auto; }
.skv-report-foot { margin-top: 40px; font-size: 12px; }
`;
var escapeHtml = (s) => s.replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);
/** JSON that cannot end its script element or break out of it. */
var scriptJson = (value) => JSON.stringify(value).replace(/</g, "\\u003c").replace(/\u2028/g, "\\u2028").replace(/\u2029/g, "\\u2029");
/**
* A report as one HTML file: the stylesheet, the data as JSON, and the
* widgets' bundle, inline. It opens from disk, in an artifact or an email
* attachment alike, and keeps no connection to where its data came from.
*/
function reportHtml(spec, bundle, opts = {}) {
	const head = `<title>${escapeHtml(spec.title)}</title>
<style id="skv-styles">${VIZ_CSS}${REPORT_CSS}</style>`;
	const body = `<div id="root"><p style="padding:16px">This report needs JavaScript to draw its charts.</p></div>
<script type="application/json" id="report-data">${scriptJson(spec)}<\/script>
<script>${bundle.replace(/<\/script/gi, "<\\/script")}<\/script>`;
	if (opts.fragment) return `${head}\n${body}\n`;
	return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="description" content="${escapeHtml(spec.subtitle ?? spec.title)}">
${head}
</head>
<body>
${body}
</body>
</html>
`;
}
//#endregion
//#region src/report/standalone.ts
function renderReport(spec, opts = {}) {
	return reportHtml(spec, _report_bundle_default, opts);
}
//#endregion
exports.renderReport = renderReport;
